import type { NextAuthOptions } from 'next-auth'
import CredentialsProvider from 'next-auth/providers/credentials'
import type { JWT } from 'next-auth/jwt'

import type { LoginResponseData, RefreshToken } from '@/types/common'

// Your API endpoint that returns JWT (for future use)
const API_URL = process.env.NEXT_PUBLIC_API_URL || 'https://api.yourdomain.com'

// Helpers
async function refreshAccessToken(token: JWT): Promise<JWT> {
  try {
    const res = await fetch(`${API_URL}/auth/refresh`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken: token.refreshToken })
    })

    if (!res.ok) throw new Error('Refresh failed')

    const data: { data: RefreshToken } = await res.json()

    return {
      ...token,
      accessToken: data.data.accessToken,
      refreshToken: data.data.refreshToken ?? token.refreshToken,
      expiresIn: data.data.expiresIn,
      error: undefined // clear any previous error
    }
  } catch {
    // Refresh failed — signal the client to sign out
    return {
      ...token,
      error: 'RefreshTokenError'
    }
  }
}

export const authOptions: NextAuthOptions = {
  session: {
    // Must outlive the upstream access token so refreshAccessToken() can run.
    // Set to the backend refresh-token TTL — shorter than this wastes the refresh flow.
    strategy: 'jwt',
    maxAge: 7 * 24 * 60 * 60 // 7 days
  },
  pages: {
    signIn: '/login',
    error: '/login'
  },
  providers: [
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        username: { label: 'Username', type: 'text' },
        password: { label: 'Password', type: 'password' }
      },
      async authorize(credentials) {
        if (!credentials?.username || !credentials?.password) {
          throw new Error('Invalid credentials')
        }

        const response = await fetch(`${API_URL}/auth/login`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            username: credentials.username,
            password: credentials.password
          })
        })

        if (!response.ok) {
          const errorData = await response.json().catch(() => null)
          const message = errorData?.message || errorData?.error || 'Invalid credentials'

          throw new Error(message)
        }

        const data: { data: LoginResponseData } = await response.json()
        const { user, accessToken, refreshToken, expiresIn, roles, permissions } = data.data

        if (!accessToken) {
          throw new Error('No token received')
        }

        return {
          id: user.userId,
          username: user.username,
          email: user.userEmail,
          fullName: user.userFullName,
          roles,
          permissions,
          accessToken,
          refreshToken,
          expiresIn
        }
      }
    })
  ],
  callbacks: {
    async jwt({ token, user, trigger, session }): Promise<JWT> {
      // Initial sign in — store token + calculate exact expiry timestamp
      if (user) {
        return {
          ...token,
          id: user.id,
          email: user.email,
          username: user.username,
          fullName: user.fullName,
          roles: user.roles,
          permissions: user.permissions,
          accessToken: user.accessToken,
          refreshToken: user.refreshToken,

          // Store the absolute expiry time in ms
          expiresIn: user.expiresIn
        }
      }

      // Handle manual session update
      if (trigger === 'update' && session) {
        return { ...token, ...session }
      }

      // token.expiresIn is an absolute ms timestamp (matches API's `expiresIn`
      // field, which is unix-ms, not a duration). Compare against Date.now() directly.
      if (Date.now() < token.expiresIn) {
        return token
      }

      //Token expired — attempt refresh
      return refreshAccessToken(token)
    },

    async session({ session, token }) {
      // Surface the error to the client so it can force sign out
      if (token.error) {
        session.error = token.error
      }

      if (token && session.user) {
        session.user.id = token.id
        session.user.email = token.email
        session.user.username = token.username
        session.user.fullName = token.fullName
        session.user.roles = token.roles
        session.user.permissions = token.permissions
        session.accessToken = token.accessToken!
        session.expiresIn = token.expiresIn
      }

      return session
    }
  }

  // events: {
  //   async signOut({ token }) {
  //     if (token) {
  //       try {
  //         await fetch(`${API_URL}/auth/logout`, {
  //           method: 'POST',
  //           headers: {
  //             'Content-Type': 'application/json',
  //             Authorization: `Bearer ${token.accessToken}`
  //           },
  //           body: JSON.stringify({
  //             refreshToken: token.refreshToken
  //           })
  //         })
  //       } catch (error) {
  //         console.error('Logout error:', error)
  //       }
  //     }
  //   }
  // }
}

