export interface LoginResponseData {
  accessToken: string
  refreshToken: string
  expiresIn: number
  type: string
  user: {
    userFullName: string
    userEmail: string
    userId: string
    username: string
  }
  roles: string[]
  permissions: string[]
}

export type RefreshToken = {
  expiresIn: number
  accessToken: string
  type: string
  refreshToken: string
}

export type PaginationMeta = {
  page: number
  limit: number
  total_rows: number
  total_pages: number
}

export type ResponseMeta = {
  request_id: string
  timestamp: string
  pagination?: PaginationMeta
}

export type ApiResponse<T> = {
  success: boolean
  code: string
  message: string
  data: T
  meta?: ResponseMeta
}

export interface QueryParams {
  search?: string
  page?: number | string
  limit?: number | string
}

export type TBaseColumnActions<T> = {
  onView: (id: string) => void
  onEdit: (id: string) => void
  onDelete: (role: T) => void
}

export interface BaseItem {
  id: string
  name: string
}
